String t(String key) {
  final v = _s[key];
  if (v == null) return key;
  return v[Lang.index];
}

/// Pick the current-language value from a {ar,en,fr,es,pt} map.
String loc(Map<String, dynamic>? m) {
  if (m == null) return '';
  final v = m[Lang.code] ?? m['en'] ?? m['ar'];
  return v == null ? '' : v.toString();
}
